<?php
namespace App\Services;
class MockMercadoPagoGateway implements MercadoPagoGatewayInterface { private function r(string $prefix,string $status='mock_ok'): GatewayResult { return new GatewayResult(true,$prefix.bin2hex(random_bytes(6)),$status,['is_mock'=>true,'environment'=>'local']); } public function createSubscription(array $data):GatewayResult{return $this->r('mock_sub_','authorized');} public function getSubscription(string $id):GatewayResult{return new GatewayResult(true,$id,'active',['is_mock'=>true]);} public function pauseSubscription(string $id):GatewayResult{return new GatewayResult(true,$id,'paused',['is_mock'=>true]);} public function cancelSubscription(string $id):GatewayResult{return new GatewayResult(true,$id,'cancelled',['is_mock'=>true]);} public function getPayment(string $id):GatewayResult{return new GatewayResult(true,$id,'approved',['is_mock'=>true]);} }
